mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM region_code
    WHERE region_code = #{regionCode}
)

SELECT id
FROM house
WHERE region_code = #{regionCode}
  AND apt_name = #{aptName}
  AND jibun = #{jibun}
  AND house_type = #{houseType}

mapper.insert:
INSERT INTO house (
    region_code, apt_name, jibun, build_year, house_type
) VALUES (
    #{regionCode}, #{aptName}, #{jibun}, #{buildYear}, #{houseType}
)

INSERT IGNORE INTO house_deal (
    house_id, deal_type, deal_amount, deposit_amount, monthly_rent,
    deal_date, area, floor
) VALUES (
    #{houseId}, #{deal.dealType}, #{deal.dealAmount},
    #{deal.depositAmount}, #{deal.monthlyRent},
    #{deal.dealDate}, #{deal.area}, #{deal.floor}
)

mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM house_deal
    WHERE house_id = #{houseId}
      AND deal_type = #{deal.dealType}
      AND deal_date = #{deal.dealDate}
      AND area = #{deal.area}
      AND floor = #{deal.floor}
      AND deal_amount = #{deal.dealAmount}
)
